function I({registerIndicator:y,sourceValues:k,nulls:g}){y({id:"oa-blma",name:"Blackman Moving Average (BLMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"blma",type:"line",title:"BLMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(s,i){const w=Math.max(1,Math.floor(Number(i.period)||10)),r=k(s,i.source??"close"),m=s.length,u=new Array(m).fill(NaN);let l=[1],f=1;const v=.42,A=.5,N=.08,P=2*Math.PI,B=4*Math.PI;for(let n=0;n<m;n++){const e=Math.min(n+1,w);if(f!==e){l=new Array(e).fill(0);let o=0;const a=1/(e-1);for(let t=0;t<e;t++){const b=t*a,x=A*Math.cos(P*b),F=N*Math.cos(B*b),d=v-x+F;l[t]=d,o+=d}const c=1/o;for(let t=0;t<e;t++)l[t]=l[t]*c;f=e}let p=0,h=0;for(let o=0;o<e;o++){const a=r[n-o];if(Number.isFinite(a)){const c=l[o];p+=a*c,h+=c}}const M=p/h;u[n]=Number.isFinite(M)?M:r[n]}return{blma:g(u)}}})}export{I as default};
